"""README.md = README.template.md with {{RESULTS}} replaced by docs/RESULTS.md (generated by evaluate.py)."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
(ROOT / "README.md").write_text((ROOT / "README.template.md").read_text().replace("{{RESULTS}}", (ROOT / "docs" / "RESULTS.md").read_text()))
print("README.md written")
